      role2 = 403102,
      role3 = 403203,
      role5 = 4103401,
      roleanim = 1.1,
      sentence = "Gavin fell silent a moment, and that pair of amber eyes seemed to become considerably more desolate.",
      next = {70}
    },
    [70] = {
      beijing = 4890,
      dialog = 2,
      idx = 4,
