      role1 = 4103000,
      role2 = 403102,
      role3 = 403203,
      role5 = 4103401,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "One time during a battle I lost consciousness... and the book didn't make it back to camp with me.",
      voice = 2,
      next = {71}
    },
    [71] = {
      beijing = 4890,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      sentence = "This was an age when lives got snuffed out at the drop of a hat, so having a book buried in the trenches was no surprising thing. I smiled a consoling smile at him.",
      next = {72}
    },
    [72] = {
      beijing = 4890,
      dhead = 2001,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      sentence = "It was just a book, after all. You making it back safe and sound is more important than any material object.",
      next = {73}
    },
    [73] = {
