      role2 = 403111,
      role3 = 403203,
      role5 = 4103401,
      roleanim = 1.1,
      ruchang = -1,
      sentence = "News doesn't travel fast on the battlefield. Our troop didn't even know the war had ended, so we didn't make it aboard the ships returning home.",
